 root.querySelectorAll("[data-decline-member]").forEach(b=>b.onclick=async()=>{const r=await supabase.from("crowspace_project_members").update({status:"declined"}).eq("project_id",id).eq("user_id",user.id).eq("status","invited");if(r.error)alert(r.error.message);else openProject(id);});
