 root.querySelectorAll("[data-milestone-assignee]").forEach(sel=>sel.onchange=async()=>{const r=await supabase.from("crowspace_project_milestones").update({assigned_to:sel.value||null,updated_at:new Date().toISOString()}).eq("id",sel.dataset.milestoneAssignee).eq("project_id",id);if(r.error){alert(r.error.message);openProject(id);}else openProject(id);});
